:root {
  --clr-bg: #fffdf6;
  --clr-border: #c8b89a;
  --clr-header-bg: #3d5a2e;
  --clr-header-text: #f0ead8;
  --clr-title: #ffffff;
  --clr-tag-bg: #6b8f4e;
  --clr-tag-text: #f0ead8;
  --clr-location: #b8d4a0;
  --clr-find-bg: #f7f3ec;
  --clr-find-border: #ddd0b8;
  --clr-find-name: #2e3a1f;
  --clr-find-latin: #7a6e5a;
  --clr-badge-edible: #4a7c3f;
  --clr-badge-edible-text: #eaf4e4;
  --clr-badge-toxic: #b03a2e;
  --clr-badge-toxic-text: #fdecea;
  --clr-stat-bg: #f0ead8;
  --clr-stat-value: #3d5a2e;
  --clr-stat-label: #7a6e5a;
  --clr-footer-bg: #eee8d8;
  --clr-footer-text: #5a5040;
  --clr-btn-bg: #3d5a2e;
  --clr-btn-text: #f0ead8;
}

article.journal-entry {
  background-color: var(--clr-bg);
  border: 2px solid var(--clr-border);
  border-radius: 12px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.entry-header {
  background-color: var(--clr-header-bg);
  padding: 14px 16px 12px;
}

.entry-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}

.entry-date {
  font-size: 12px;
  color: var(--clr-header-text);
  opacity: 0.85;
}

.entry-tag {
  background-color: var(--clr-tag-bg);
  color: var(--clr-tag-text);
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.entry-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--clr-title);
  margin: 0 0 4px;
  line-height: 1.1;
}

.entry-location {
  font-size: 12px;
  color: var(--clr-location);
  margin: 0;
}

.entry-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  flex: 1;
}

.finds-list {
  list-style: none;
  margin: 0;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.find-item {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--clr-find-bg);
  border: 1px solid var(--clr-find-border);
  border-radius: 8px;
  padding: 8px 10px;
}

.find-icon {
  font-size: 20px;
  line-height: 1;
}

.find-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.find-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--clr-find-name);
  line-height: 1;
}

.find-latin {
  font-size: 11px;
  color: var(--clr-find-latin);
  font-style: italic;
  line-height: 1;
}

.find-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.find-badge.edible {
  background-color: var(--clr-badge-edible);
  color: var(--clr-badge-edible-text);
}

.find-badge.toxic {
  background-color: var(--clr-badge-toxic);
  color: var(--clr-badge-toxic-text);
}

.entry-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background-color: var(--clr-find-border);
  border-left: 1px solid var(--clr-find-border);
  width: 110px;
  flex-shrink: 0;
}

.stat-block {
  background-color: var(--clr-stat-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 6px;
  gap: 2px;
}

.stat-value {
  font-size: 15px;
  font-weight: 800;
  color: var(--clr-stat-value);
  line-height: 1;
}

.stat-label {
  font-size: 10px;
  color: var(--clr-stat-label);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.entry-footer {
  background-color: var(--clr-footer-bg);
  border-top: 1px solid var(--clr-border);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-note {
  font-size: 12px;
  color: var(--clr-footer-text);
}

.log-btn {
  background-color: var(--clr-btn-bg);
  color: var(--clr-btn-text);
  border: none;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  cursor: pointer;
}
